<?php

/**
 * Watch Tower PHP SDK 0.1.0 - single-file build (generated by build/build.php, do not edit).
 *
 *     require __DIR__.'/watchtower.php';
 *     WatchTower::init(['token' => '...', 'base_url' => 'https://watchtower.example.com']);
 *
 * @license MIT
 */

declare(strict_types=1);

namespace WatchTower {

use WatchTower\Records\RecordFactory;
use WatchTower\Support\Guard;
use WatchTower\Support\Location;
use WatchTower\Support\Redactor;
use WatchTower\Support\RoutePattern;
use WatchTower\Support\Sql;
use WatchTower\Support\Text;
use WatchTower\Support\TraceContext;
use WatchTower\Transport\HttpClient;
use WatchTower\Transport\Ingest;
use WatchTower\Transport\Spool;

/**
 * The SDK core: owns the current execution (request or command), buffers its
 * records and hands them to the transport when the execution ends.
 */
final class Client
{
    /** PSR-3 levels by RFC 5424 severity (0 = most severe). */
    public const LOG_LEVELS = [
        'emergency' => 0, 'alert' => 1, 'critical' => 2, 'error' => 3,
        'warning' => 4, 'notice' => 5, 'info' => 6, 'debug' => 7,
    ];

    private const HELLO_INTERVAL_SECONDS = 86400;

    private static bool $helloSentThisProcess = false;

    public readonly Redactor $redactor;

    public readonly Location $location;

    public readonly RecordFactory $records;

    public readonly Ingest $ingest;

    private ?Execution $execution = null;

    private int $explicitCommands = 0;

    private ?int $responseBytes = null;

    private int $outputLevel = 0;

    private bool $finished = false;

    public function __construct(public readonly Config $config, ?HttpClient $http = null)
    {
        $this->redactor = new Redactor($config->redactKeys, $config->redactHeaders);
        $this->location = new Location($config->basePath, $config->locationSkip);
        $this->records = new RecordFactory($config, $this->redactor, $this->location);
        $this->ingest = new Ingest(
            $config,
            $http ?? $config->httpClient ?? Ingest::defaultHttpClient(),
            new Spool($config->spoolDir, $config->spoolMaxBytes),
        );
    }

    public function execution(): ?Execution
    {
        return $this->execution;
    }

    public function isActive(): bool
    {
        return $this->config->enabled && $this->execution !== null && ! $this->execution->ignored;
    }

    /**
     * Begin observing an HTTP request described by a `$_SERVER`-like array.
     *
     * @param  array<string, mixed>  $server
     */
    public function startRequest(array $server, ?float $startedAt = null): Execution
    {
        $startedAt ??= is_numeric($server['REQUEST_TIME_FLOAT'] ?? null) ? (float) $server['REQUEST_TIME_FLOAT'] : microtime(true);
        $execution = new Execution('request', $startedAt, $this->roll($this->config->sampleRate));
        $execution->bootstrapEndedAt = max($startedAt, microtime(true));

        $method = strtoupper((string) ($server['REQUEST_METHOD'] ?? 'GET'));
        $uri = (string) ($server['REQUEST_URI'] ?? '/');
        $path = (string) (parse_url($uri, PHP_URL_PATH) ?? '/');
        $path = $path === '' ? '/' : $path;
        $headers = self::headersFrom($server);
        $https = strtolower((string) ($server['HTTPS'] ?? ''));
        $scheme = ($https !== '' && $https !== 'off') || (string) ($server['REQUEST_SCHEME'] ?? '') === 'https' ? 'https' : 'http';
        $host = (string) ($server['HTTP_HOST'] ?? $server['SERVER_NAME'] ?? 'localhost');

        $execution->preview = Text::tiny($method.' '.$path);
        $execution->meta = [
            'method' => $method,
            'url' => $scheme.'://'.$host.$uri,
            'path' => $path,
            'route_name' => '',
            'route_methods' => [$method],
            'route_domain' => '',
            'route_path' => RoutePattern::fromPath($path),
            'route_action' => '',
            'ip' => $this->clientIp($server),
            'request_size' => is_numeric($server['CONTENT_LENGTH'] ?? null) ? (int) $server['CONTENT_LENGTH'] : 0,
            'headers' => $this->config->captures('headers') ? $headers : [],
        ];
        $execution->ignored = ! $this->config->captures('requests') || $this->isIgnoredPath($path);

        $this->begin($execution);

        if ($this->config->captures('trace_context') && isset($headers['traceparent'][0])) {
            $parent = TraceContext::parse($headers['traceparent'][0]);

            if ($parent !== null) {
                $this->push($this->records->traceLink($execution, $parent, microtime(true)));
            }
        }

        return $execution;
    }

    /**
     * Begin observing a CLI command or script.
     */
    public function startCommand(string $name, ?string $command = null, string $class = '', ?float $startedAt = null): Execution
    {
        $startedAt ??= microtime(true);
        $execution = new Execution('command', $startedAt, $this->roll($this->config->sampleRate));
        $execution->bootstrapEndedAt = max($startedAt, microtime(true));
        $execution->preview = Text::tiny($name);
        $execution->meta = ['name' => $name, 'command' => $command ?? $name, 'class' => $class];
        $execution->ignored = ! $this->config->captures('commands');

        $this->begin($execution);

        return $execution;
    }

    public function begin(Execution $execution): void
    {
        $this->execution = $execution;
        $this->finished = false;
    }

    /**
     * Name the route of the current request (`/users/{id}`), which also becomes its group.
     *
     * @param  list<string>|null  $methods
     */
    public function route(string $path, ?string $name = null, ?string $action = null, ?array $methods = null, ?string $domain = null): void
    {
        if ($this->execution === null || $this->execution->source !== 'request') {
            return;
        }

        $meta = &$this->execution->meta;
        $meta['route_path'] = $path === '' ? '' : '/'.ltrim($path, '/');
        $meta['route_name'] = $name ?? $meta['route_name'];
        $meta['route_action'] = $action ?? $meta['route_action'];
        $meta['route_methods'] = $methods !== null ? array_values(array_map('strtoupper', $methods)) : $meta['route_methods'];
        $meta['route_domain'] = $domain ?? $meta['route_domain'];
    }

    public function user(string|int|null $id, ?string $name = null, ?string $username = null): void
    {
        if ($this->execution === null) {
            return;
        }

        if ($id === null || (string) $id === '') {
            $this->execution->userId = '';
            $this->execution->userDetails = null;

            return;
        }

        $this->execution->userId = Text::tiny((string) $id);
        $this->execution->userDetails = ['id' => (string) $id, 'name' => (string) $name, 'username' => (string) $username];
    }

    /** Do not report the current execution at all. */
    public function ignore(): void
    {
        if ($this->execution !== null) {
            $this->execution->ignored = true;
        }
    }

    public function setExitCode(int $code): void
    {
        if ($this->execution !== null) {
            $this->execution->exitCode = $code;
        }
    }

    public function captureException(\Throwable $e, bool $handled = true): void
    {
        Guard::safely(function () use ($e, $handled): void {
            if (! $this->isActive() || ! $this->config->captures('exceptions')) {
                return;
            }

            $execution = $this->execution;
            $execution->counters['exceptions']++;

            if (! $handled) {
                $execution->hasUnhandledException = true;

                if ($execution->exceptionPreview === '') {
                    $execution->exceptionPreview = Text::tiny($this->redactor->text($e->getMessage()));
                }

                if ($this->roll($this->config->exceptionSampleRate)) {
                    $execution->forceKeep = true;
                }
            }

            $this->push($this->records->exception($execution, $e, $handled, microtime(true)));
        });
    }

    /**
     * @param  array<array-key, mixed>  $context
     * @param  array<array-key, mixed>  $extra
     */
    public function log(string $level, string|\Stringable $message, array $context = [], array $extra = [], ?float $timestamp = null): void
    {
        Guard::safely(function () use ($level, $message, $context, $extra, $timestamp): void {
            $level = strtolower($level);

            if (! $this->isActive() || ! $this->config->captures('logs') || ! isset(self::LOG_LEVELS[$level])
                || self::LOG_LEVELS[$level] > (self::LOG_LEVELS[$this->config->logLevel] ?? 7)) {
                return;
            }

            $this->execution->counters['logs']++;
            $this->push($this->records->log($this->execution, $level, (string) $message, $context, $extra, $timestamp ?? microtime(true)));
        });
    }

    /**
     * Record a database query. Literals are stripped before anything is stored.
     */
    public function query(string $sql, float $startedAt, int $durationMicros, string $connection = 'default', ?string $file = null, ?int $line = null): void
    {
        Guard::safely(function () use ($sql, $startedAt, $durationMicros, $connection, $file, $line): void {
            if (! $this->isActive() || ! $this->config->captures('queries')) {
                return;
            }

            if ($file === null) {
                [$file, $line] = $this->location->find(debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS, 30));
            }

            $this->execution->counters['queries']++;

            if ($this->config->slowQueryMs !== null && $durationMicros >= $this->config->slowQueryMs * 1000) {
                $this->execution->forceKeep = true;
            }

            $this->push($this->records->query(
                $this->execution,
                Sql::stripLiterals($sql, $this->config->stripNumericLiterals),
                $startedAt,
                $durationMicros,
                $connection,
                $file,
                (int) $line,
            ));
        });
    }

    public function outgoingRequest(string $method, string $url, float $startedAt, int $durationMicros, int $requestSize, int $responseSize, int $statusCode): void
    {
        Guard::safely(function () use ($method, $url, $startedAt, $durationMicros, $requestSize, $responseSize, $statusCode): void {
            if (! $this->isActive() || ! $this->config->captures('outgoing_requests')) {
                return;
            }

            $this->execution->counters['outgoing_requests']++;
            $this->push($this->records->outgoingRequest($this->execution, $method, $url, $startedAt, $durationMicros, $requestSize, $responseSize, $statusCode));
        });
    }

    /** A `traceparent` value for an outgoing call made by the current execution. */
    public function traceparent(): ?string
    {
        if ($this->execution === null || ! $this->config->captures('trace_context')) {
            return null;
        }

        return TraceContext::outgoing($this->execution->traceId);
    }

    /**
     * Run a CLI task as its own command execution and report it (with its
     * output when enabled). The callback's return value is passed through: an
     * int is the exit code, `false` means 1, anything else 0.
     *
     * @template T
     *
     * @param  callable(): T  $callback
     * @return T
     */
    public function runCommand(string $name, callable $callback, ?bool $captureOutput = null): mixed
    {
        $outer = $this->execution;
        $outerFinished = $this->finished;
        $this->explicitCommands++;
        $execution = $this->startCommand($name, $name, '');
        $execution->ignored = false;
        $capture = ($captureOutput ?? $this->config->captures('command_output')) && $this->config->enabled;
        $level = null;

        if ($capture) {
            $execution->meta['output'] = '';
            $execution->meta['output_truncated'] = false;
            $max = $this->config->outputMaxBytes;

            $started = ob_start(static function (string $buffer) use ($execution, $max): string {
                $output = $execution->meta['output'].$buffer;

                if (strlen($output) > $max * 2) {
                    $output = Text::tail($output, $max);
                    $execution->meta['output_truncated'] = true;
                }

                $execution->meta['output'] = $output;

                return $buffer;
            }, 1);
            $level = $started ? ob_get_level() : null;
        }

        try {
            $result = $callback();
            $execution->exitCode = is_int($result) ? $result : ($result === false ? 1 : 0);

            return $result;
        } catch (\Throwable $e) {
            $this->captureException($e, false);
            $execution->exitCode = 1;

            throw $e;
        } finally {
            if ($level !== null && ob_get_level() >= $level) {
                while (ob_get_level() > $level) {
                    @ob_end_flush();
                }
                @ob_end_flush();
            }

            $this->finish();
            $this->execution = $outer;
            $this->finished = $outerFinished;
        }
    }

    /**
     * Send what is buffered so far (the execution keeps running).
     */
    public function flush(): void
    {
        Guard::safely(function (): void {
            if ($this->execution === null || $this->execution->ignored) {
                return;
            }

            if ($this->shouldKeep($this->execution, microtime(true))) {
                $records = $this->execution->records;
                $this->execution->records = [];
                $this->deliver($records);
            }
        });
    }

    /**
     * End the current execution: add its request/command (and user, output)
     * records, apply sampling and deliver.
     *
     * @param  array<string, mixed>  $response  status_code / response_size overrides.
     */
    public function finish(array $response = []): void
    {
        Guard::safely(function () use ($response): void {
            $execution = $this->execution;

            if ($execution === null || $this->finished) {
                return;
            }

            $this->finished = true;
            $endedAt = microtime(true);
            $execution->stage = 'terminating';

            if ($execution->ignored || ! $this->config->enabled) {
                $this->deliver([]);

                return;
            }

            $records = $execution->records;

            if ($execution->dropped > 0) {
                $records[] = $this->records->log($execution, 'warning', sprintf(
                    'Watch Tower PHP SDK dropped %d records of this %s (limit %d per execution).',
                    $execution->dropped,
                    $execution->source,
                    $this->config->maxRecords,
                ), ['dropped' => $execution->droppedTypes], [], $endedAt);
                $execution->counters['logs']++;
            }

            if ($execution->source === 'request') {
                $status = (int) ($response['status_code'] ?? 0);
                if ($execution->hasUnhandledException && ($status === 0 || $status < 500)) {
                    $status = 500;
                }

                $records[] = $this->records->request($execution, [
                    ...$execution->meta,
                    'status_code' => $status,
                    'response_size' => (int) ($response['response_size'] ?? 0),
                    'payload' => $this->payload($execution, $status),
                ], $endedAt);
            } elseif (! ($this->explicitCommands > 0 && ($execution->meta['auto'] ?? false) && $records === [])) {
                if ($execution->hasUnhandledException && ($execution->exitCode ?? 0) === 0) {
                    $execution->exitCode = ($execution->meta['auto'] ?? false) ? 255 : 1;
                }

                $records[] = $this->records->command($execution, $endedAt);

                if (isset($execution->meta['output']) && is_string($execution->meta['output'])) {
                    $output = $execution->meta['output'];
                    $truncated = (bool) ($execution->meta['output_truncated'] ?? false) || strlen($output) > $this->config->outputMaxBytes;
                    $records[] = $this->records->output($execution, Text::tail($output, $this->config->outputMaxBytes), $truncated, $endedAt);
                }
            }

            if ($execution->userDetails !== null) {
                $records[] = $this->records->user($execution->userDetails, $endedAt);
            }

            $execution->records = [];
            $this->deliver($this->shouldKeep($execution, $endedAt) ? $records : []);
        });
    }

    /**
     * Registered (as the last shutdown function) by WatchTower::init().
     */
    public function shutdown(?ErrorHandler $errors = null): void
    {
        Guard::safely(function () use ($errors): void {
            $errors?->handleShutdown();

            $response = [];

            if ($this->execution?->source === 'request' && PHP_SAPI !== 'cli') {
                $finish = $this->config->finishRequest && (function_exists('fastcgi_finish_request') || function_exists('litespeed_finish_request'));

                if ($finish && $this->outputLevel > 0) {
                    // Flush buffers opened above the size counter so it sees the whole body.
                    while (ob_get_level() > $this->outputLevel && @ob_end_flush()) {
                    }
                }

                $code = http_response_code();
                $response = ['status_code' => is_int($code) ? $code : 200, 'response_size' => $this->responseSize()];

                if ($finish) {
                    function_exists('fastcgi_finish_request') ? @fastcgi_finish_request() : @litespeed_finish_request();
                }
            }

            $this->finish($response);
        });
    }

    /**
     * Count response bytes with a pass-through output buffer (chunk size 1, so
     * output is never held back).
     */
    public function countResponseBytes(): void
    {
        Guard::safely(function (): void {
            $this->responseBytes = 0;

            if (ob_start(function (string $buffer): string {
                $this->responseBytes += strlen($buffer);

                return $buffer;
            }, 1)) {
                $this->outputLevel = ob_get_level();
            }
        });
    }

    /**
     * Records waiting in the current execution's buffer (for tests and debugging).
     *
     * @return list<array<string, mixed>>
     */
    public function buffered(): array
    {
        return $this->execution->records ?? [];
    }

    /**
     * @param  array<string, mixed>  $record
     */
    public function push(array $record): void
    {
        $execution = $this->execution;

        if ($execution === null || $execution->ignored) {
            return;
        }

        if (count($execution->records) >= $this->config->maxRecords) {
            $execution->dropped++;
            $type = (string) ($record['t'] ?? 'unknown');
            $execution->droppedTypes[$type] = ($execution->droppedTypes[$type] ?? 0) + 1;

            return;
        }

        $execution->records[] = $record;
    }

    /**
     * @param  list<array<string, mixed>>  $records
     */
    private function deliver(array $records): void
    {
        if (! $this->config->enabled) {
            return;
        }

        if ($this->helloDue()) {
            array_unshift($records, $this->records->hello($this->features(), microtime(true)));
            $this->markHelloSent();
        }

        $this->ingest->deliver($records);
    }

    private function shouldKeep(Execution $execution, float $now): bool
    {
        if ($execution->sampled || $execution->forceKeep) {
            return true;
        }

        return $this->config->slowRequestMs !== null
            && ($now - $execution->startedAt) * 1000 >= $this->config->slowRequestMs;
    }

    private function roll(float $rate): bool
    {
        return match (true) {
            $rate >= 1.0 => true,
            $rate <= 0.0 => false,
            default => mt_rand() / mt_getrandmax() < $rate,
        };
    }

    /**
     * @return list<string>
     */
    private function features(): array
    {
        return array_values(array_filter([
            $this->config->captures('trace_context') ? 'trace_context' : null,
            $this->config->captures('command_output') ? 'output' : null,
        ]));
    }

    private function helloDue(): bool
    {
        if (self::$helloSentThisProcess || ! $this->config->captures('hello') || ! $this->config->canSend()) {
            return false;
        }

        $marker = $this->helloMarker();
        $modified = is_file($marker) ? @filemtime($marker) : false;

        return $modified === false || $modified < time() - self::HELLO_INTERVAL_SECONDS;
    }

    private function markHelloSent(): void
    {
        self::$helloSentThisProcess = true;

        if ($this->ingest->spool()->ensureDirectory()) {
            @touch($this->helloMarker());
        }
    }

    private function helloMarker(): string
    {
        return $this->config->spoolDir.DIRECTORY_SEPARATOR.'hello-'.$this->config->tokenId();
    }

    /** @internal Tests reset the per-process hello flag. */
    public static function resetProcessState(): void
    {
        self::$helloSentThisProcess = false;
    }

    private function responseSize(): int
    {
        foreach (headers_list() as $header) {
            if (stripos($header, 'content-length:') === 0 && is_numeric($length = trim(substr($header, 15)))) {
                return (int) $length;
            }
        }

        return $this->responseBytes ?? 0;
    }

    /**
     * Like Nightwatch: the request payload is only kept for 500 responses, and
     * only when explicitly enabled.
     */
    private function payload(Execution $execution, int $status): string
    {
        if ($status !== 500 || in_array($execution->meta['method'] ?? 'GET', ['GET', 'HEAD', 'OPTIONS', 'TRACE'], true)) {
            return '';
        }

        if (! $this->config->captures('payload')) {
            return '{"_nightwatch_error":"NOT_ENABLED"}';
        }

        return Text::text(Text::json($this->redactor->data($_POST)));
    }

    /**
     * @param  array<string, mixed>  $server
     */
    private function clientIp(array $server): string
    {
        if ($this->config->trustedProxyHeader !== null) {
            $key = 'HTTP_'.strtoupper(str_replace('-', '_', $this->config->trustedProxyHeader));
            $value = $server[$key] ?? null;

            if (is_string($value)) {
                $candidate = trim(explode(',', $value)[0]);

                if (filter_var($candidate, FILTER_VALIDATE_IP) !== false) {
                    return $candidate;
                }
            }
        }

        return (string) ($server['REMOTE_ADDR'] ?? '');
    }

    private function isIgnoredPath(string $path): bool
    {
        foreach ($this->config->ignorePaths as $pattern) {
            if ($pattern === $path || (function_exists('fnmatch') && fnmatch($pattern, $path))) {
                return true;
            }
        }

        return false;
    }

    /**
     * Request headers in Symfony HeaderBag::all() shape: lower-case name => list of values.
     *
     * @param  array<string, mixed>  $server
     * @return array<string, list<string>>
     */
    public static function headersFrom(array $server): array
    {
        $headers = [];

        foreach ($server as $key => $value) {
            if (! is_string($value) && ! is_numeric($value)) {
                continue;
            }

            $name = match (true) {
                str_starts_with((string) $key, 'HTTP_') => substr((string) $key, 5),
                in_array($key, ['CONTENT_TYPE', 'CONTENT_LENGTH', 'CONTENT_MD5'], true) => (string) $key,
                default => null,
            };

            if ($name !== null) {
                $headers[strtolower(str_replace('_', '-', $name))] = [(string) $value];
            }
        }

        return $headers;
    }
}

}

namespace WatchTower {

use Composer\Autoload\ClassLoader;
use WatchTower\Transport\HttpClient;

/**
 * Resolved SDK options. Every option has a safe default; token and base URL
 * also fall back to the WATCHTOWER_TOKEN / WATCHTOWER_URL environment variables.
 */
final class Config
{
    /** Same pattern Watch Tower applies server-side (config/watchtower.php redaction.key_pattern). */
    public const DEFAULT_REDACT_KEYS = '/pass(word|wd|phrase)?|secret|token|api[_-]?key|private[_-]?key|credential|authorization|cookie|session|credit[_-]?card|card[_-]?number|cvv|cvc|ssn|iban/i';

    /** @var list<string> */
    public const DEFAULT_REDACT_HEADERS = [
        'authorization', 'proxy-authorization', 'cookie', 'set-cookie', 'x-xsrf-token',
        'x-csrf-token', 'x-api-key', 'x-auth-token', 'php-auth-pw', 'x-amz-security-token',
    ];

    /** @var array<string, bool> */
    public const DEFAULT_CAPTURE = [
        'requests' => true,
        'commands' => true,
        'exceptions' => true,
        'errors' => true,
        'deprecations' => false,
        'fatal_errors' => true,
        'logs' => true,
        'queries' => true,
        'outgoing_requests' => true,
        'headers' => true,
        'response_size' => true,
        'payload' => false,
        'code_snippets' => true,
        'command_output' => false,
        'trace_context' => true,
        'hello' => true,
    ];

    public bool $enabled;

    public ?string $token;

    public string $baseUrl;

    public ?string $environment;

    public ?string $service;

    public string $deploy;

    public string $server;

    public float $sampleRate;

    public float $exceptionSampleRate;

    /** @var array<string, bool> */
    public array $capture;

    public string $redactKeys;

    /** @var list<string> */
    public array $redactHeaders;

    /** @var list<string> */
    public array $ignorePaths;

    public ?float $slowRequestMs;

    public ?float $slowQueryMs;

    public ?string $trustedProxyHeader;

    public string $mode;

    public string $spoolDir;

    public int $spoolMaxBytes;

    public int $spoolDrainBatches;

    public int $maxRecords;

    public float $connectTimeout;

    public float $timeout;

    public bool $finishRequest;

    public string $basePath;

    public ?int $errorReporting;

    public ?HttpClient $httpClient;

    public int $outputMaxBytes;

    public ?string $framework;

    public string $logLevel;

    public bool $stripNumericLiterals;

    /** @var list<string> */
    public array $locationSkip;

    /**
     * @param  array<string, mixed>  $options
     */
    public function __construct(array $options = [])
    {
        $env = static fn (string $name): ?string => is_string($value = getenv($name)) && $value !== '' ? $value : (isset($_ENV[$name]) && is_string($_ENV[$name]) && $_ENV[$name] !== '' ? $_ENV[$name] : null);

        $this->token = self::nullableString($options['token'] ?? $env('WATCHTOWER_TOKEN'));
        $this->baseUrl = rtrim((string) ($options['base_url'] ?? $env('WATCHTOWER_URL') ?? ''), '/');
        $this->enabled = (bool) ($options['enabled'] ?? self::bool($env('WATCHTOWER_ENABLED'), true));
        $this->environment = self::nullableString($options['environment'] ?? $env('WATCHTOWER_ENV'));
        $this->service = self::nullableString($options['service'] ?? $env('WATCHTOWER_SERVICE'));
        $this->deploy = (string) ($options['deploy'] ?? $env('WATCHTOWER_DEPLOY') ?? '');
        $this->server = (string) ($options['server'] ?? $env('WATCHTOWER_SERVER') ?? (gethostname() ?: 'unknown'));
        $this->sampleRate = self::rate($options['sample_rate'] ?? $env('WATCHTOWER_SAMPLE_RATE') ?? 1.0);
        $this->exceptionSampleRate = self::rate($options['exception_sample_rate'] ?? 1.0);

        $capture = is_array($options['capture'] ?? null) ? $options['capture'] : [];
        $this->capture = self::DEFAULT_CAPTURE;
        foreach ($capture as $flag => $value) {
            $this->capture[(string) $flag] = (bool) $value;
        }

        $this->redactKeys = (string) ($options['redact_keys'] ?? self::DEFAULT_REDACT_KEYS);
        if (@preg_match($this->redactKeys, '') === false) {
            $this->redactKeys = self::DEFAULT_REDACT_KEYS;
        }

        $this->redactHeaders = array_values(array_unique(array_map(
            'strtolower',
            array_map('strval', [...self::DEFAULT_REDACT_HEADERS, ...(array) ($options['redact_headers'] ?? [])]),
        )));
        $this->ignorePaths = array_values(array_map('strval', (array) ($options['ignore_paths'] ?? ['/health'])));
        $this->slowRequestMs = isset($options['slow_request_ms']) ? (float) $options['slow_request_ms'] : null;
        $this->slowQueryMs = isset($options['slow_query_ms']) ? (float) $options['slow_query_ms'] : null;
        $this->trustedProxyHeader = self::nullableString($options['trusted_proxy_header'] ?? null);
        $this->mode = in_array($options['mode'] ?? null, ['auto', 'spool'], true) ? $options['mode'] : 'auto';
        $this->spoolDir = rtrim((string) ($options['spool_dir'] ?? $env('WATCHTOWER_SPOOL_DIR') ?? sys_get_temp_dir().DIRECTORY_SEPARATOR.'watchtower'), '/\\');
        $this->spoolMaxBytes = max(1024, (int) ($options['spool_max_bytes'] ?? 50 * 1024 * 1024));
        $this->spoolDrainBatches = max(0, (int) ($options['spool_drain_batches'] ?? 5));
        $this->maxRecords = max(10, (int) ($options['max_records'] ?? 500));
        $this->connectTimeout = max(0.1, (float) ($options['connect_timeout'] ?? 1.0));
        $this->timeout = max($this->connectTimeout, (float) ($options['timeout'] ?? 2.0));
        $this->finishRequest = (bool) ($options['finish_request'] ?? true);
        $this->basePath = rtrim((string) ($options['base_path'] ?? self::guessBasePath()), '/\\');
        $this->errorReporting = isset($options['error_reporting']) ? (int) $options['error_reporting'] : null;
        $this->httpClient = ($options['http_client'] ?? null) instanceof HttpClient ? $options['http_client'] : null;
        $this->outputMaxBytes = max(1024, (int) ($options['output_max_bytes'] ?? 65536));
        $this->framework = self::nullableString($options['framework'] ?? null);
        $this->logLevel = strtolower((string) ($options['log_level'] ?? 'debug'));
        $this->stripNumericLiterals = (bool) ($options['strip_numeric_literals'] ?? true);
        $this->locationSkip = array_values(array_map('strval', (array) ($options['location_skip'] ?? [])));
    }

    public function captures(string $flag): bool
    {
        return $this->capture[$flag] ?? false;
    }

    /** Whether the SDK has everything it needs to deliver records. */
    public function canSend(): bool
    {
        return $this->enabled && $this->token !== null && $this->baseUrl !== '';
    }

    public function ingestUrl(): string
    {
        return $this->baseUrl.'/api/ingest/v1';
    }

    /** A short, non-reversible id of the token for marker file names. */
    public function tokenId(): string
    {
        return substr(hash('xxh128', (string) $this->token), 0, 12);
    }

    private static function guessBasePath(): string
    {
        if (class_exists(ClassLoader::class, false)) {
            $file = (new \ReflectionClass(ClassLoader::class))->getFileName();

            if (is_string($file)) {
                return dirname($file, 3);
            }
        }

        $root = $_SERVER['DOCUMENT_ROOT'] ?? '';

        if (is_string($root) && $root !== '') {
            return $root;
        }

        return getcwd() ?: '';
    }

    private static function nullableString(mixed $value): ?string
    {
        return is_scalar($value) && (string) $value !== '' ? (string) $value : null;
    }

    private static function rate(mixed $value): float
    {
        return is_numeric($value) ? max(0.0, min(1.0, (float) $value)) : 1.0;
    }

    private static function bool(?string $value, bool $default): bool
    {
        if ($value === null) {
            return $default;
        }

        return ! in_array(strtolower($value), ['0', 'false', 'off', 'no', ''], true);
    }
}

}

namespace WatchTower {

use WatchTower\Support\Guard;

/**
 * Global exception, error and fatal-error capture. Previous handlers are
 * chained, `error_reporting()` and the `@` operator are respected, and PHP's
 * own behaviour (logging, display, exit code 255) is preserved.
 */
final class ErrorHandler
{
    private const FATAL = E_ERROR | E_PARSE | E_CORE_ERROR | E_COMPILE_ERROR | E_USER_ERROR | E_RECOVERABLE_ERROR;

    /** Identical warnings reported per execution before further repeats are ignored. */
    private const MAX_REPEATS = 5;

    /** @var callable|null */
    private $previousExceptionHandler = null;

    /** @var callable|null */
    private $previousErrorHandler = null;

    /** @var array<string, int> */
    private array $seen = [];

    private ?string $seenFor = null;

    private bool $installed = false;

    public function __construct(private readonly Client $client) {}

    public function install(): void
    {
        if ($this->installed) {
            return;
        }

        $this->installed = true;
        $config = $this->client->config;

        if ($config->captures('exceptions')) {
            $this->previousExceptionHandler = set_exception_handler([$this, 'handleException']);
        }

        if ($config->captures('errors')) {
            $this->previousErrorHandler = set_error_handler([$this, 'handleError']);
        }
    }

    public function handleException(\Throwable $e): void
    {
        Guard::safely(function () use ($e): void {
            $this->client->captureException($e, false);

            if ($this->client->execution()?->source === 'command') {
                $this->client->setExitCode(255);
            }
        });

        if ($this->previousExceptionHandler !== null) {
            ($this->previousExceptionHandler)($e);

            return;
        }

        // No previous handler: let PHP report it exactly as it would have
        // ("PHP Fatal error: Uncaught ...", HTTP 500, exit code 255).
        set_exception_handler(null);

        throw $e;
    }

    public function handleError(int $level, string $message, string $file = '', int $line = 0): bool
    {
        $reported = (error_reporting() & $level) !== 0
            && (($this->client->config->errorReporting ?? E_ALL) & $level) !== 0;

        if ($reported) {
            Guard::safely(fn () => $this->report($level, $message, $file, $line));
        }

        if ($this->previousErrorHandler !== null) {
            return (bool) ($this->previousErrorHandler)($level, $message, $file, $line);
        }

        // Fall through to PHP's standard handler (log / display as configured).
        return false;
    }

    public function handleShutdown(): void
    {
        Guard::safely(function (): void {
            $error = error_get_last();

            if ($error === null || ($error['type'] & self::FATAL) === 0 || ! $this->client->config->captures('fatal_errors')) {
                return;
            }

            $execution = $this->client->execution();

            // An uncaught exception we already reported ends as "Uncaught ..." fatal error.
            if ($execution?->hasUnhandledException && str_starts_with($error['message'], 'Uncaught ')) {
                return;
            }

            $message = (string) preg_replace('/\s+Stack trace:.*$/s', '', $error['message']);
            $this->client->captureException(new FatalError($message, 0, $error['type'], $error['file'], $error['line']), false);

            if ($execution?->source === 'command') {
                $this->client->setExitCode(255);
            }
        });
    }

    private function report(int $level, string $message, string $file, int $line): void
    {
        $deprecation = ($level & (E_DEPRECATED | E_USER_DEPRECATED)) !== 0;

        if ($deprecation && ! $this->client->config->captures('deprecations')) {
            return;
        }

        $execution = $this->client->execution();
        $trace = $execution?->traceId;

        if ($trace !== $this->seenFor) {
            $this->seen = [];
            $this->seenFor = $trace;
        }

        $key = $level.'|'.$file.'|'.$line;
        $this->seen[$key] = ($this->seen[$key] ?? 0) + 1;

        if ($this->seen[$key] > self::MAX_REPEATS) {
            return;
        }

        // Warnings and notices are reported as handled; E_USER_ERROR stops the script.
        $this->client->captureException(new \ErrorException($message, 0, $level, $file, $line), $level !== E_USER_ERROR);
    }
}

}

namespace WatchTower {

use WatchTower\Support\Uuid;

/**
 * State of the request or command currently being observed: its trace id,
 * the counters Nightwatch reports, and the records buffered for it.
 */
final class Execution
{
    public string $traceId;

    public string $preview = '';

    public string $stage = 'action';

    public string $userId = '';

    /** @var array{id: string, name: string, username: string}|null */
    public ?array $userDetails = null;

    /** @var array<string, int> */
    public array $counters = [
        'exceptions' => 0,
        'logs' => 0,
        'queries' => 0,
        'lazy_loads' => 0,
        'jobs_queued' => 0,
        'mail' => 0,
        'notifications' => 0,
        'outgoing_requests' => 0,
        'files_read' => 0,
        'files_written' => 0,
        'cache_events' => 0,
        'hydrated_models' => 0,
    ];

    public string $exceptionPreview = '';

    public bool $hasUnhandledException = false;

    /** Set when something (an exception, a slow query) means the execution is kept even if not sampled. */
    public bool $forceKeep = false;

    public bool $ignored = false;

    /** @var list<array<string, mixed>> */
    public array $records = [];

    public int $dropped = 0;

    /** @var array<string, int> */
    public array $droppedTypes = [];

    /**
     * Request: route and HTTP details; command: name, command line and class.
     *
     * @var array<string, mixed>
     */
    public array $meta = [];

    public ?int $exitCode = null;

    public ?float $bootstrapEndedAt = null;

    /**
     * @param  'request'|'command'  $source
     */
    public function __construct(
        public readonly string $source,
        public readonly float $startedAt,
        public readonly bool $sampled = true,
        ?string $traceId = null,
    ) {
        $this->traceId = $traceId ?? Uuid::v4();
    }

    /** Nightwatch uses the trace id as the execution id of requests and commands. */
    public function id(): string
    {
        return $this->traceId;
    }

    /**
     * The execution header copied into every in-execution record (QuerySensor.php:60-72).
     *
     * @return array<string, string>
     */
    public function header(): array
    {
        return [
            'trace_id' => $this->traceId,
            'execution_source' => $this->source,
            'execution_id' => $this->id(),
            'execution_preview' => $this->preview,
            'execution_stage' => $this->stage,
            'user' => $this->userId,
        ];
    }
}

}

namespace WatchTower {

/**
 * A fatal PHP error (E_ERROR, E_PARSE, ...) found by error_get_last() at shutdown.
 */
final class FatalError extends \ErrorException {}

}

namespace WatchTower\Http {

use WatchTower\Client;

/**
 * Times a curl_exec() call and records it as an `outgoing-request`.
 */
final class CurlTracer
{
    /**
     * @param  list<string>|null  $headers  The request headers; when given they are set on the
     *                                      handle together with a W3C `traceparent` header.
     */
    public static function exec(?Client $client, \CurlHandle $handle, ?array $headers = null): string|bool
    {
        if ($client !== null && $headers !== null) {
            try {
                $traceparent = $client->traceparent();

                if ($traceparent !== null && ! self::hasHeader($headers, 'traceparent')) {
                    $headers[] = 'traceparent: '.$traceparent;
                }

                curl_setopt($handle, CURLOPT_HTTPHEADER, $headers);
            } catch (\Throwable) {
                // Fall through to the plain call.
            }
        }

        $startedAt = microtime(true);
        $result = curl_exec($handle);
        $endedAt = microtime(true);

        if ($client !== null) {
            try {
                $info = curl_getinfo($handle);
                $method = defined('CURLINFO_EFFECTIVE_METHOD') ? (string) curl_getinfo($handle, CURLINFO_EFFECTIVE_METHOD) : '';

                $client->outgoingRequest(
                    $method !== '' ? $method : 'GET',
                    (string) ($info['url'] ?? ''),
                    $startedAt,
                    (int) round(($endedAt - $startedAt) * 1_000_000),
                    (int) max(0, $info['size_upload'] ?? 0),
                    (int) max(0, $info['size_download'] ?? 0),
                    $result === false ? 0 : (int) ($info['http_code'] ?? 0),
                );
            } catch (\Throwable) {
                // Recording must never affect the call.
            }
        }

        return $result;
    }

    /**
     * Add a `traceparent` to a list of "Name: value" header lines (for code
     * that sets CURLOPT_HTTPHEADER itself).
     *
     * @param  list<string>  $headers
     * @return list<string>
     */
    public static function withTraceparent(?Client $client, array $headers): array
    {
        $traceparent = $client?->traceparent();

        if ($traceparent !== null && ! self::hasHeader($headers, 'traceparent')) {
            $headers[] = 'traceparent: '.$traceparent;
        }

        return $headers;
    }

    /**
     * @param  list<string>  $headers
     */
    private static function hasHeader(array $headers, string $name): bool
    {
        foreach ($headers as $header) {
            if (is_string($header) && stripos(ltrim($header), $name.':') === 0) {
                return true;
            }
        }

        return false;
    }
}

}

namespace WatchTower\Http {

use GuzzleHttp\Promise\Create;
use WatchTower\Client;

/**
 * Guzzle middleware recording `outgoing-request` records and adding a W3C
 * `traceparent` header:
 *
 *     $stack = \GuzzleHttp\HandlerStack::create();
 *     $stack->push(WatchTower::guzzleMiddleware(), 'watchtower');
 *     $http = new \GuzzleHttp\Client(['handler' => $stack]);
 */
final class GuzzleMiddleware
{
    /**
     * @param  \Closure(): ?Client  $client
     */
    public static function create(\Closure $client): callable
    {
        return static function (callable $handler) use ($client): callable {
            return static function ($request, array $options) use ($handler, $client) {
                $sdk = null;

                try {
                    $sdk = $client();
                    $traceparent = $sdk?->traceparent();

                    if ($traceparent !== null && ! $request->hasHeader('traceparent')) {
                        $request = $request->withHeader('traceparent', $traceparent);
                    }
                } catch (\Throwable) {
                    // Send the request untouched.
                }

                $startedAt = microtime(true);
                $record = static function ($response) use ($sdk, $request, $startedAt): void {
                    if ($sdk === null) {
                        return;
                    }

                    try {
                        $sdk->outgoingRequest(
                            $request->getMethod(),
                            (string) $request->getUri(),
                            $startedAt,
                            (int) round((microtime(true) - $startedAt) * 1_000_000),
                            self::size($request),
                            $response !== null ? self::size($response) : 0,
                            $response !== null ? (int) $response->getStatusCode() : 0,
                        );
                    } catch (\Throwable) {
                        // Never affect the request.
                    }
                };

                return $handler($request, $options)->then(
                    static function ($response) use ($record) {
                        $record($response);

                        return $response;
                    },
                    static function ($reason) use ($record) {
                        $response = is_object($reason) && method_exists($reason, 'getResponse') ? $reason->getResponse() : null;
                        $record($response);

                        return Create::rejectionFor($reason);
                    },
                );
            };
        };
    }

    /**
     * Nightwatch OutgoingRequestSensor::resolveMessageSize(): body size, else Content-Length, else 0.
     */
    private static function size(object $message): int
    {
        $size = $message->getBody()->getSize();

        if ($size !== null) {
            return (int) $size;
        }

        $length = $message->getHeader('content-length')[0] ?? null;

        return is_numeric($length) ? (int) $length : 0;
    }
}

}

namespace WatchTower\Log {

use WatchTower\Client;

/**
 * PSR-3 compatible logger writing Nightwatch `log` records into the current
 * execution. Signatures are deliberately loose so the subclass can implement
 * every psr/log major version (1, 2 and 3).
 */
abstract class BaseLogger
{
    /**
     * @param  \Closure(): ?Client  $client
     */
    public function __construct(private readonly \Closure $client) {}

    public function emergency($message, array $context = []): void
    {
        $this->log('emergency', $message, $context);
    }

    public function alert($message, array $context = []): void
    {
        $this->log('alert', $message, $context);
    }

    public function critical($message, array $context = []): void
    {
        $this->log('critical', $message, $context);
    }

    public function error($message, array $context = []): void
    {
        $this->log('error', $message, $context);
    }

    public function warning($message, array $context = []): void
    {
        $this->log('warning', $message, $context);
    }

    public function notice($message, array $context = []): void
    {
        $this->log('notice', $message, $context);
    }

    public function info($message, array $context = []): void
    {
        $this->log('info', $message, $context);
    }

    public function debug($message, array $context = []): void
    {
        $this->log('debug', $message, $context);
    }

    /**
     * @param  mixed  $level  A PSR-3 level name.
     * @param  string|\Stringable  $message
     * @param  array<array-key, mixed>  $context
     */
    public function log($level, $message, array $context = []): void
    {
        try {
            if (! is_string($level) || (! is_string($message) && ! $message instanceof \Stringable)) {
                return;
            }

            ($this->client)()?->log($level, $message, $context);
        } catch (\Throwable) {
            // Logging must never break the application.
        }
    }
}

}

namespace WatchTower\Log {

use Psr\Log\LoggerInterface;

if (interface_exists(LoggerInterface::class)) {
    /**
     * PSR-3 logger for Watch Tower (psr/log is installed).
     */
    final class Logger extends BaseLogger implements LoggerInterface {}
} else {
    /**
     * PSR-3 compatible logger for Watch Tower (psr/log is not installed).
     */
    final class Logger extends BaseLogger {}
}

}

namespace WatchTower\Log {

use Monolog\Handler\AbstractProcessingHandler;
use Monolog\LogRecord;
use WatchTower\Client;
use WatchTower\WatchTower;

if (class_exists(AbstractProcessingHandler::class)) {
    /**
     * Monolog (2.x and 3.x) handler that forwards records to Watch Tower:
     *
     *     $logger->pushHandler(new \WatchTower\Log\MonologHandler());
     */
    class MonologHandler extends AbstractProcessingHandler
    {
        /** @var \Closure(): ?Client */
        private \Closure $client;

        /**
         * @param  int|string|object  $level  Minimum Monolog level.
         * @param  (\Closure(): ?Client)|null  $client
         */
        public function __construct($level = 'debug', bool $bubble = true, ?\Closure $client = null)
        {
            parent::__construct($level, $bubble);
            $this->client = $client ?? static fn (): ?Client => WatchTower::client();
        }

        /**
         * @param  LogRecord|array<string, mixed>  $record
         */
        protected function write($record): void
        {
            try {
                if ($record instanceof LogRecord) {
                    [$level, $message, $context, $extra, $time] = [$record->level->toPsrLogLevel(), $record->message, $record->context, $record->extra, $record->datetime];
                } else {
                    [$level, $message, $context, $extra, $time] = [strtolower((string) $record['level_name']), (string) $record['message'], (array) ($record['context'] ?? []), (array) ($record['extra'] ?? []), $record['datetime'] ?? null];
                }

                $timestamp = $time instanceof \DateTimeInterface ? (float) $time->format('U.u') : microtime(true);

                ($this->client)()?->log($level, $message, $context, $extra, $timestamp);
            } catch (\Throwable) {
                // Never break the application's logging.
            }
        }
    }
}

}

namespace WatchTower\Pdo {

use WatchTower\Client;
use WatchTower\WatchTower;

/**
 * Drop-in PDO that records every successful query (prepare/execute, query,
 * exec) as a Nightwatch `query` record: literals stripped, duration in
 * microseconds, connection name and the application file/line that ran it.
 *
 *     $pdo = new TracedPdo('mysql:host=db;dbname=app', 'user', 'secret', [], 'mysql');
 */
class TracedPdo extends \PDO
{
    private string $connectionName;

    /** @var \Closure(): ?Client */
    private \Closure $client;

    /**
     * @param  array<int, mixed>|null  $options
     * @param  string|null  $connectionName  Shown as the query's connection (default: the driver name).
     * @param  (\Closure(): ?Client)|null  $client
     */
    public function __construct(string $dsn, ?string $username = null, ?string $password = null, ?array $options = null, ?string $connectionName = null, ?\Closure $client = null)
    {
        parent::__construct($dsn, $username, $password, $options);

        $this->client = $client ?? static fn (): ?Client => WatchTower::client();
        $this->connectionName = $connectionName ?? (string) $this->getAttribute(\PDO::ATTR_DRIVER_NAME);

        // Custom statement classes are not allowed on persistent connections.
        if (! ($options[\PDO::ATTR_PERSISTENT] ?? false)) {
            $this->setAttribute(\PDO::ATTR_STATEMENT_CLASS, [TracedStatement::class, [$this]]);
        }
    }

    public function connectionName(): string
    {
        return $this->connectionName;
    }

    public function exec(string $statement): int|false
    {
        $startedAt = microtime(true);
        $result = parent::exec($statement);

        if ($result !== false) {
            $this->recordQuery($statement, $startedAt, microtime(true));
        }

        return $result;
    }

    public function query(string $query, ?int $fetchMode = null, mixed ...$fetchModeArgs): \PDOStatement|false
    {
        $startedAt = microtime(true);
        $result = $fetchMode === null ? parent::query($query) : parent::query($query, $fetchMode, ...$fetchModeArgs);

        if ($result !== false) {
            $this->recordQuery($query, $startedAt, microtime(true));
        }

        return $result;
    }

    /** @internal Called by TracedPdo and TracedStatement. */
    public function recordQuery(string $sql, float $startedAt, float $endedAt): void
    {
        try {
            ($this->client)()?->query($sql, $startedAt, (int) round(($endedAt - $startedAt) * 1_000_000), $this->connectionName);
        } catch (\Throwable) {
            // Never interfere with the query itself.
        }
    }
}

}

namespace WatchTower\Pdo {

/**
 * Statement class installed by TracedPdo: times every execute().
 */
class TracedStatement extends \PDOStatement
{
    protected function __construct(private readonly TracedPdo $connection) {}

    public function execute(?array $params = null): bool
    {
        $startedAt = microtime(true);
        $result = parent::execute($params);

        if ($result) {
            $this->connection->recordQuery($this->queryString, $startedAt, microtime(true));
        }

        return $result;
    }
}

}

namespace WatchTower\Records {

use WatchTower\Config;
use WatchTower\Execution;
use WatchTower\Support\Location;
use WatchTower\Support\Redactor;
use WatchTower\Support\Sql;
use WatchTower\Support\Text;
use WatchTower\WatchTower;

/**
 * Builds records in the Laravel Nightwatch v1 wire format (laravel/nightwatch
 * src/Sensors/*) plus the Watch Tower `wt-*` records this SDK emits.
 *
 * Units: timestamps are float UNIX seconds, durations integer microseconds,
 * memory bytes; headers, context, trace and payload are JSON strings.
 */
final class RecordFactory
{
    /** Stack frames that get source code snippets (ExceptionSensor caps at 10). */
    private const MAX_CODE_FRAMES = 10;

    public function __construct(
        private readonly Config $config,
        private readonly Redactor $redactor,
        private readonly Location $location,
    ) {}

    /**
     * @return array{v: int, t: string, timestamp: float, deploy: string, server: string}
     */
    private function base(string $type, float $timestamp, int $version = 1): array
    {
        return [
            'v' => $version,
            't' => $type,
            'timestamp' => $timestamp,
            'deploy' => $this->config->deploy,
            'server' => $this->config->server,
        ];
    }

    /**
     * RequestSensor. `$http` holds method, url, route_*, ip, status_code, sizes and headers.
     *
     * @param  array<string, mixed>  $http
     * @return array<string, mixed>
     */
    public function request(Execution $execution, array $http, float $endedAt): array
    {
        $routeMethods = array_values(array_map('strval', (array) ($http['route_methods'] ?? [])));
        sort($routeMethods);
        $routeDomain = (string) ($http['route_domain'] ?? '');
        $routePath = (string) ($http['route_path'] ?? '');
        $bootstrapEnd = $execution->bootstrapEndedAt ?? $execution->startedAt;
        $bootstrap = self::micros($bootstrapEnd - $execution->startedAt);
        $action = self::micros($endedAt - $bootstrapEnd);

        return [
            ...$this->base('request', $execution->startedAt),
            '_group' => hash('xxh128', implode('|', $routeMethods).",{$routeDomain},{$routePath}"),
            'trace_id' => $execution->traceId,
            'user' => $execution->userId,
            'method' => Text::tiny(strtoupper((string) ($http['method'] ?? 'GET'))),
            'url' => Text::text($this->redactor->url((string) ($http['url'] ?? ''))),
            'route_name' => Text::tiny((string) ($http['route_name'] ?? '')),
            'route_methods' => $routeMethods,
            'route_domain' => Text::tiny($routeDomain),
            'route_path' => Text::tiny($routePath),
            'route_action' => Text::tiny((string) ($http['route_action'] ?? '')),
            'ip' => Text::tiny((string) ($http['ip'] ?? '')),
            'duration' => $bootstrap + $action,
            'status_code' => (int) ($http['status_code'] ?? 0),
            'request_size' => (int) ($http['request_size'] ?? 0),
            'response_size' => (int) ($http['response_size'] ?? 0),
            'bootstrap' => $bootstrap,
            'before_middleware' => 0,
            'action' => $action,
            'render' => 0,
            'after_middleware' => 0,
            'sending' => 0,
            'terminating' => 0,
            ...$execution->counters,
            'peak_memory_usage' => memory_get_peak_usage(true),
            'exception_preview' => Text::tiny($execution->exceptionPreview),
            'context' => '{}',
            'headers' => Text::text(Text::json($this->redactor->headers((array) ($http['headers'] ?? [])))),
            'payload' => Text::text((string) ($http['payload'] ?? '')),
        ];
    }

    /**
     * CommandSensor.
     *
     * @return array<string, mixed>
     */
    public function command(Execution $execution, float $endedAt): array
    {
        $name = (string) ($execution->meta['name'] ?? 'php');
        $exitCode = $execution->exitCode ?? 0;
        $bootstrapEnd = $execution->bootstrapEndedAt ?? $execution->startedAt;
        $bootstrap = self::micros($bootstrapEnd - $execution->startedAt);
        $action = self::micros($endedAt - $bootstrapEnd);

        return [
            ...$this->base('command', $execution->startedAt),
            '_group' => hash('xxh128', $name),
            'trace_id' => $execution->traceId,
            'class' => (string) ($execution->meta['class'] ?? ''),
            'name' => $name,
            'command' => $this->redactor->text((string) ($execution->meta['command'] ?? $name)),
            'exit_code' => $exitCode < 0 || $exitCode > 255 ? 255 : $exitCode,
            'duration' => $bootstrap + $action,
            'bootstrap' => $bootstrap,
            'action' => $action,
            'terminating' => 0,
            ...$execution->counters,
            'peak_memory_usage' => memory_get_peak_usage(true),
            'exception_preview' => Text::tiny($execution->exceptionPreview),
            'context' => '{}',
        ];
    }

    /**
     * QuerySensor. `$sql` must already have its literals stripped.
     *
     * @return array<string, mixed>
     */
    public function query(Execution $execution, string $sql, float $startedAt, int $duration, string $connection, string $file, int $line): array
    {
        return [
            ...$this->base('query', $startedAt),
            '_group' => Sql::group($connection, $sql),
            ...$execution->header(),
            'sql' => Text::medium($sql),
            'file' => Text::tiny($file),
            'line' => $line,
            'duration' => max(0, $duration),
            'connection' => Text::tiny($connection),
            'connection_type' => '',
        ];
    }

    /**
     * ExceptionSensor (wire version 3, as Nightwatch sends it).
     *
     * @return array<string, mixed>
     */
    public function exception(Execution $execution, \Throwable $e, bool $handled, float $timestamp): array
    {
        [$file, $line] = $this->location->forThrowable($e);
        $code = (string) $e->getCode();

        return [
            ...$this->base('exception', $timestamp, 3),
            '_group' => hash('xxh128', $e::class.','.$code.','.$file.','.$line),
            ...$execution->header(),
            'class' => Text::text($e::class),
            'file' => Text::text($file),
            'line' => $line,
            'message' => Text::text($this->redactor->text($e->getMessage())),
            'code' => Text::text($code),
            'trace' => Text::medium($this->trace($e)),
            'handled' => $handled,
            'php_version' => PHP_VERSION,
            'laravel_version' => '',
        ];
    }

    /**
     * LogSensor.
     *
     * @param  array<array-key, mixed>  $context
     * @param  array<array-key, mixed>  $extra
     * @return array<string, mixed>
     */
    public function log(Execution $execution, string $level, string $message, array $context, array $extra, float $timestamp): array
    {
        return [
            ...$this->base('log', $timestamp),
            ...$execution->header(),
            'level' => Text::tiny($level),
            'message' => Text::text($this->redactor->text($message)),
            'context' => Text::text(Text::json($this->redactor->data((array) Text::normalize($context)))),
            'extra' => Text::text(Text::json($this->redactor->data((array) Text::normalize($extra)))),
        ];
    }

    /**
     * OutgoingRequestSensor.
     *
     * @return array<string, mixed>
     */
    public function outgoingRequest(Execution $execution, string $method, string $url, float $startedAt, int $duration, int $requestSize, int $responseSize, int $statusCode): array
    {
        $url = (string) preg_replace('#^([a-z][a-z0-9+.-]*://)[^/@?\#]*@#i', '$1', $url);
        $host = (string) (parse_url($url, PHP_URL_HOST) ?? '');

        return [
            ...$this->base('outgoing-request', $startedAt),
            '_group' => hash('xxh128', $host),
            ...$execution->header(),
            'host' => Text::tiny($host),
            'method' => Text::tiny(strtoupper($method)),
            'url' => Text::text($this->redactor->url($url)),
            'duration' => max(0, $duration),
            'request_size' => max(0, $requestSize),
            'response_size' => max(0, $responseSize),
            'status_code' => $statusCode,
        ];
    }

    /**
     * UserSensor (no deploy/server header, exactly like Nightwatch).
     *
     * @param  array{id: string, name: string, username: string}  $details
     * @return array<string, mixed>
     */
    public function user(array $details, float $timestamp): array
    {
        return [
            'v' => 1,
            't' => 'user',
            'timestamp' => $timestamp,
            'id' => Text::tiny($details['id']),
            'name' => Text::tiny($details['name']),
            'username' => Text::tiny($details['username']),
        ];
    }

    /**
     * Watch Tower agent header (contract: v, t, timestamp, deploy, server, agent_version).
     *
     * @return array<string, mixed>
     */
    private function agentBase(string $type, float $timestamp): array
    {
        return [...$this->base($type, $timestamp), 'agent_version' => WatchTower::VERSION];
    }

    /**
     * `wt-hello` with the PHP SDK extras (sdk, sdk_version, framework, service, environment).
     *
     * @param  list<string>  $features
     * @return array<string, mixed>
     */
    public function hello(array $features, float $timestamp): array
    {
        return [
            ...$this->agentBase('wt-hello', $timestamp),
            'laravel_version' => null,
            'php_version' => PHP_VERSION,
            'features' => $features,
            'schedule_catchup_version' => null,
            'sdk' => 'php',
            'sdk_version' => WatchTower::VERSION,
            'framework' => $this->config->framework,
            'service' => $this->config->service,
            'environment' => $this->config->environment,
        ];
    }

    /**
     * `wt-trace-link`: this execution was called by a traced caller.
     *
     * @param  array{parent_trace_id: string, parent_span_id: string}  $parent
     * @return array<string, mixed>
     */
    public function traceLink(Execution $execution, array $parent, float $timestamp): array
    {
        return [
            ...$this->base('wt-trace-link', $timestamp),
            'trace_id' => $execution->traceId,
            'agent_version' => WatchTower::VERSION,
            'execution_source' => $execution->source,
            'execution_id' => $execution->id(),
            'execution_stage' => $execution->stage,
            'user' => $execution->userId,
            'parent_trace_id' => $parent['parent_trace_id'],
            'parent_span_id' => $parent['parent_span_id'],
        ];
    }

    /**
     * `wt-output` of a command (group = command group hash, xxh128 of its name).
     *
     * @return array<string, mixed>
     */
    public function output(Execution $execution, string $output, bool $truncated, float $timestamp): array
    {
        $name = (string) ($execution->meta['name'] ?? 'php');

        return [
            ...$this->agentBase('wt-output', $timestamp),
            'kind' => 'command',
            'group' => hash('xxh128', $name),
            'trace_id' => $execution->traceId,
            'name' => $name,
            'exit_code' => $execution->exitCode ?? 0,
            'output' => $this->redactor->text($output),
            'truncated' => $truncated,
        ];
    }

    /**
     * ExceptionSensor::serializeTrace(): the throw location first, then each
     * frame as {file: "path:line", source: "Class->method(types)", code: {line: text}|null}.
     */
    private function trace(\Throwable $e): string
    {
        $snippets = 0;
        $files = [];
        $trace = [[
            'file' => $this->location->normalize($e->getFile()).':'.$e->getLine(),
            'source' => '',
            'code' => $this->snippet($e->getFile(), $e->getLine(), $snippets, $files),
        ]];

        foreach ($e->getTrace() as $frame) {
            if ($this->isSdkClass($frame['class'] ?? null)) {
                continue;
            }

            $file = isset($frame['file']) && is_string($frame['file']) ? $this->location->normalize($frame['file']) : '[internal function]';

            if (isset($frame['line']) && is_int($frame['line'])) {
                $file .= ':'.$frame['line'];
            }

            $source = ($frame['class'] ?? '').($frame['type'] ?? '').($frame['function'] ?? '').'(';

            if (isset($frame['args']) && is_array($frame['args']) && $frame['args'] !== []) {
                $args = array_map(static fn (mixed $argument): string => match (gettype($argument)) {
                    'NULL' => 'null',
                    'boolean' => 'bool',
                    'integer' => 'int',
                    'double' => 'float',
                    'array' => 'array',
                    'object' => $argument::class,
                    'string' => 'string',
                    default => 'resource',
                }, $frame['args']);

                if (! array_is_list($args)) {
                    $args = array_map(static fn (string $value, int|string $key): string => "{$key}: {$value}", $args, array_keys($args));
                }

                $source .= implode(', ', $args);
            }

            $trace[] = [
                'file' => $file,
                'source' => $source.')',
                'code' => $this->snippet($frame['file'] ?? null, $frame['line'] ?? null, $snippets, $files),
            ];
        }

        $json = json_encode($trace, Text::JSON_FLAGS);

        return is_string($json) ? $json : '[]';
    }

    /**
     * Five lines of application source around a line, keyed by line number.
     *
     * @param  array<string, list<string>|null>  $files
     */
    private function snippet(mixed $file, mixed $line, int &$count, array &$files): ?\stdClass
    {
        if (! $this->config->captures('code_snippets') || $count >= self::MAX_CODE_FRAMES
            || ! is_string($file) || ! is_int($line) || ! $this->location->isApplicationFile($file)) {
            return null;
        }

        if (! array_key_exists($file, $files)) {
            $lines = is_file($file) && is_readable($file) && filesize($file) < 2_000_000 ? @file($file, FILE_IGNORE_NEW_LINES) : false;
            $files[$file] = is_array($lines) ? $lines : null;
        }

        $lines = $files[$file];

        if ($lines === null) {
            return null;
        }

        $code = new \stdClass;

        for ($number = max(1, $line - 5); $number <= min(count($lines), $line + 5); $number++) {
            $code->{(string) $number} = rtrim($lines[$number - 1], "\r\n");
        }

        $count++;

        return $code;
    }

    /** @var array<string, bool> */
    private array $sdkClasses = [];

    /** Frames of SDK classes (error handler, guards) are left out of traces. */
    private function isSdkClass(mixed $class): bool
    {
        if (! is_string($class) || ! str_starts_with($class, 'WatchTower\\')) {
            return false;
        }

        return $this->sdkClasses[$class] ??= (static function (string $class, Location $location): bool {
            try {
                $file = (new \ReflectionClass($class))->getFileName();

                return is_string($file) && $location->isSdkFile($file);
            } catch (\Throwable) {
                return false;
            }
        })($class, $this->location);
    }

    public static function micros(float $seconds): int
    {
        return max(0, (int) round($seconds * 1_000_000));
    }
}

}

namespace WatchTower\Support {

/**
 * Runs SDK code so that nothing it does can ever throw into the host application.
 */
final class Guard
{
    /**
     * @template T
     *
     * @param  callable(): T  $callback
     * @param  T  $fallback
     * @return T
     */
    public static function safely(callable $callback, mixed $fallback = null): mixed
    {
        try {
            return $callback();
        } catch (\Throwable) {
            return $fallback;
        }
    }
}

}

namespace WatchTower\Support {

/**
 * Finds the application frame responsible for a query, call or error and
 * turns absolute paths into paths relative to the project root.
 */
final class Location
{
    /** @var list<string> */
    private array $sdkPaths;

    /**
     * @param  list<string>  $skip  Extra path fragments to treat as library code.
     */
    public function __construct(
        private readonly string $basePath,
        private readonly array $skip = [],
    ) {
        $this->sdkPaths = basename(__DIR__) === 'Support'
            ? [dirname(__DIR__).DIRECTORY_SEPARATOR, dirname(__DIR__, 2).DIRECTORY_SEPARATOR.'wordpress'.DIRECTORY_SEPARATOR]
            : [__FILE__];
    }

    public function isSdkFile(string $file): bool
    {
        foreach ($this->sdkPaths as $path) {
            if ($file === $path || str_starts_with($file, $path)) {
                return true;
            }
        }

        foreach ($this->skip as $fragment) {
            if ($fragment !== '' && str_contains($file, $fragment)) {
                return true;
            }
        }

        return false;
    }

    public function isVendorFile(string $file): bool
    {
        return str_contains($file, DIRECTORY_SEPARATOR.'vendor'.DIRECTORY_SEPARATOR);
    }

    /** Application code (not SDK, not vendor), used to decide where code snippets are read. */
    public function isApplicationFile(string $file): bool
    {
        return ! $this->isSdkFile($file) && ! $this->isVendorFile($file);
    }

    /**
     * First application frame of a backtrace, else the first non-SDK frame.
     *
     * @param  list<array<string, mixed>>  $trace
     * @return array{0: string, 1: int}
     */
    public function find(array $trace): array
    {
        $fallback = null;

        foreach ($trace as $frame) {
            $file = $frame['file'] ?? null;

            if (! is_string($file) || $this->isSdkFile($file)) {
                continue;
            }

            $line = (int) ($frame['line'] ?? 0);

            if (! $this->isVendorFile($file)) {
                return [$this->normalize($file), $line];
            }

            $fallback ??= [$this->normalize($file), $line];
        }

        return $fallback ?? ['', 0];
    }

    /**
     * Location of a throwable: its own file unless that is library code.
     *
     * @return array{0: string, 1: int}
     */
    public function forThrowable(\Throwable $e): array
    {
        if ($this->isApplicationFile($e->getFile())) {
            return [$this->normalize($e->getFile()), $e->getLine()];
        }

        foreach ($e->getTrace() as $frame) {
            if (isset($frame['file']) && is_string($frame['file']) && $this->isApplicationFile($frame['file'])) {
                return [$this->normalize($frame['file']), (int) ($frame['line'] ?? 0)];
            }
        }

        return [$this->normalize($e->getFile()), $e->getLine()];
    }

    public function normalize(string $file): string
    {
        if ($this->basePath !== '' && str_starts_with($file, $this->basePath.DIRECTORY_SEPARATOR)) {
            return substr($file, strlen($this->basePath) + 1);
        }

        return $file;
    }
}

}

namespace WatchTower\Support {

/**
 * Client-side scrubbing of secrets, mirroring Watch Tower's server-side Redactor
 * so nothing sensitive leaves the host in the first place.
 */
final class Redactor
{
    public const MASK = '[redacted]';

    /**
     * @param  list<string>  $headers  Lower-case header names that are always masked.
     */
    public function __construct(
        private readonly string $keyPattern,
        private readonly array $headers = [],
    ) {}

    public function isSensitiveKey(string $key): bool
    {
        return preg_match($this->keyPattern, $key) === 1;
    }

    /**
     * Mask header values by name (exact list or key pattern).
     *
     * @param  array<string, list<string>>  $headers
     * @return array<string, list<string>>
     */
    public function headers(array $headers): array
    {
        $clean = [];

        foreach ($headers as $name => $values) {
            $name = strtolower((string) $name);

            if (in_array($name, ['php-auth-user', 'php-auth-pw', 'php-auth-digest'], true)) {
                continue;
            }

            $clean[$name] = in_array($name, $this->headers, true) || $this->isSensitiveKey($name)
                ? array_map(static fn (): string => self::MASK, $values === [] ? [''] : $values)
                : array_map('strval', $values);
        }

        return $clean;
    }

    /**
     * Recursively mask values whose keys look like credentials.
     *
     * @param  array<array-key, mixed>  $data
     * @return array<array-key, mixed>
     */
    public function data(array $data, int $depth = 0): array
    {
        if ($depth > 12) {
            return [self::MASK];
        }

        $clean = [];

        foreach ($data as $key => $value) {
            if (is_string($key) && $this->isSensitiveKey($key) && ! is_array($value)) {
                $clean[$key] = self::MASK;
            } elseif (is_array($value)) {
                $clean[$key] = $this->data($value, $depth + 1);
            } elseif (is_string($value)) {
                $clean[$key] = $this->text($value);
            } else {
                $clean[$key] = $value;
            }
        }

        return $clean;
    }

    /**
     * Mask sensitive query-string parameters and drop user info from a URL.
     */
    public function url(string $url): string
    {
        $url = (string) preg_replace('#^([a-z][a-z0-9+.-]*://)[^/@?\#]*@#i', '$1', $url);
        $query = parse_url($url, PHP_URL_QUERY);

        if (! is_string($query) || $query === '') {
            return $url;
        }

        $parts = array_map(function (string $pair): string {
            [$key] = explode('=', $pair, 2);

            return $this->isSensitiveKey(urldecode($key)) ? $key.'='.self::MASK : $pair;
        }, explode('&', $query));

        return str_replace('?'.$query, '?'.implode('&', $parts), $url);
    }

    /**
     * Mask bearer tokens, JWTs and key=value secrets that end up in free text.
     */
    public function text(string $text): string
    {
        $text = (string) preg_replace('/\b(Bearer|Basic)\s+[A-Za-z0-9\-._~+\/]+=*/i', '$1 '.self::MASK, $text);
        $text = (string) preg_replace('/\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/', self::MASK, $text);

        return (string) preg_replace_callback(
            '/\b([A-Za-z_][A-Za-z0-9_.-]*)=([^\s&"\']+)/',
            fn (array $m): string => $this->isSensitiveKey($m[1]) ? $m[1].'='.self::MASK : $m[0],
            $text,
        );
    }
}

}

namespace WatchTower\Support {

/**
 * Turns a concrete URL path into a route-like pattern so requests group
 * sensibly when the application does not name its routes:
 * `/users/42/posts/9f1c...` becomes `/users/{id}/posts/{uuid}`.
 */
final class RoutePattern
{
    public static function fromPath(string $path): string
    {
        $path = '/'.ltrim($path, '/');

        if ($path === '/') {
            return '/';
        }

        $segments = array_map(static function (string $segment): string {
            return match (true) {
                $segment === '' => '',
                preg_match('/^\d+$/', $segment) === 1 => '{id}',
                preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i', $segment) === 1 => '{uuid}',
                preg_match('/^[0-9a-f]{16,}$/i', $segment) === 1 => '{hash}',
                preg_match('/^[0-9A-HJKMNP-TV-Z]{26}$/', $segment) === 1 => '{ulid}',
                default => $segment,
            };
        }, explode('/', substr($path, 1)));

        return '/'.implode('/', $segments);
    }

    /**
     * Turn a WordPress REST route regex (`/wp/v2/posts/(?P<id>[\d]+)`) into `/wp/v2/posts/{id}`.
     */
    public static function fromRegex(string $route): string
    {
        $pattern = (string) preg_replace('/\(\?P<([A-Za-z0-9_]+)>(?:[^()]|\([^()]*\))*\)/', '{$1}', $route);

        return '/'.ltrim(str_replace(['^', '$'], '', $pattern), '/');
    }
}

}

namespace WatchTower\Support {

/**
 * SQL helpers: literal stripping (so values never leave the host) and the
 * Nightwatch query group hash.
 */
final class Sql
{
    /**
     * Replace quoted string literals exactly like Watch Tower's server-side
     * Redactor::sql() does ('...' becomes '?'), and optionally bare numeric
     * literals (42 becomes ?), so raw queries group like prepared ones.
     */
    public static function stripLiterals(string $sql, bool $numbers = true): string
    {
        $sql = (string) preg_replace("/'(?:[^'\\\\]|\\\\.|'')*'/", "'?'", $sql);

        if ($numbers) {
            $sql = (string) preg_replace('/(?<![\w$.:`"\]\[?])-?\b\d+(?:\.\d+)?\b(?![\w`"])/', '?', $sql);
        }

        return $sql;
    }

    /**
     * Nightwatch QuerySensor::hash(): xxh128("{connection},{sql}") with
     * `in (?, ?)` and multi-row `values (...)` collapsed.
     */
    public static function group(string $connection, string $sql): string
    {
        $normalized = preg_replace('/in \([\d?\s,]+\)/', 'in (...?)', $sql) ?? $sql;

        if (str_contains($normalized, 'insert')) {
            $normalized = preg_replace('/values [(?,\s)]+/', 'values ...', $normalized) ?? $normalized;
        }

        return hash('xxh128', "{$connection},{$normalized}");
    }
}

}

namespace WatchTower\Support {

/**
 * Size limits and JSON encoding used by Nightwatch's record serializers.
 */
final class Text
{
    public const JSON_FLAGS = JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION
        | JSON_INVALID_UTF8_SUBSTITUTE | JSON_PARTIAL_OUTPUT_ON_ERROR;

    public static function tiny(string $value): string
    {
        return self::restrict($value, 255);
    }

    public static function text(string $value): string
    {
        return self::restrict($value, 65_535);
    }

    public static function medium(string $value): string
    {
        return self::restrict($value, 16_777_215);
    }

    /** Cut to at most $bytes bytes without splitting a UTF-8 character. */
    public static function restrict(string $value, int $bytes): string
    {
        if (strlen($value) <= $bytes) {
            return $value;
        }

        return function_exists('mb_strcut') ? mb_strcut($value, 0, $bytes, 'UTF-8') : substr($value, 0, $bytes);
    }

    /** Keep the last $bytes bytes (command output), on a character boundary. */
    public static function tail(string $value, int $bytes): string
    {
        if (strlen($value) <= $bytes) {
            return $value;
        }

        return function_exists('mb_strcut')
            ? mb_strcut($value, strlen($value) - $bytes, $bytes, 'UTF-8')
            : substr($value, -$bytes);
    }

    /** JSON for nested wire fields; arrays with string keys (or empty ones) become objects. */
    public static function json(mixed $value, bool $object = true): string
    {
        if ($object && is_array($value)) {
            $value = (object) $value;
        }

        $json = json_encode($value, self::JSON_FLAGS);

        return is_string($json) ? $json : ($object ? '{}' : 'null');
    }

    /**
     * Make arbitrary log context JSON-safe (throwables, objects, resources).
     */
    public static function normalize(mixed $value, int $depth = 0): mixed
    {
        if ($depth > 8) {
            return '[depth limit]';
        }

        return match (true) {
            $value === null, is_scalar($value) => $value,
            is_array($value) => array_map(static fn (mixed $item): mixed => self::normalize($item, $depth + 1), $value),
            $value instanceof \Throwable => [
                'class' => $value::class,
                'message' => $value->getMessage(),
                'code' => $value->getCode(),
                'file' => $value->getFile().':'.$value->getLine(),
            ],
            $value instanceof \JsonSerializable => self::normalize(Guard::safely(static fn (): mixed => $value->jsonSerialize(), $value::class), $depth + 1),
            $value instanceof \DateTimeInterface => $value->format(\DateTimeInterface::RFC3339_EXTENDED),
            $value instanceof \Stringable => (string) $value,
            is_object($value) => '['.$value::class.']',
            default => '[resource]',
        };
    }
}

}

namespace WatchTower\Support {

/**
 * W3C Trace Context (`traceparent`) built from and read into trace ids,
 * identical to the Laravel Watch Tower agent.
 */
final class TraceContext
{
    private const PATTERN = '/^([0-9a-f]{2})-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/';

    /**
     * "00-{trace id without dashes}-{random 16 hex}-01", or null when the trace id is not a
     * 32-hex-digit id (with or without dashes).
     */
    public static function outgoing(?string $traceId): ?string
    {
        $hex = strtolower(str_replace('-', '', (string) $traceId));

        if (preg_match('/^[0-9a-f]{32}$/', $hex) !== 1 || $hex === str_repeat('0', 32)) {
            return null;
        }

        return '00-'.$hex.'-'.bin2hex(random_bytes(8)).'-01';
    }

    /**
     * @return array{parent_trace_id: string, parent_span_id: string}|null
     */
    public static function parse(?string $header): ?array
    {
        $header = strtolower(trim((string) $header));

        if (preg_match(self::PATTERN, $header, $matches) !== 1
            || $matches[1] === 'ff'
            || $matches[2] === str_repeat('0', 32)
            || $matches[3] === str_repeat('0', 16)) {
            return null;
        }

        return ['parent_trace_id' => $matches[2], 'parent_span_id' => $matches[3]];
    }
}

}

namespace WatchTower\Support {

/**
 * Random (v4) UUIDs, the format Nightwatch uses for trace ids.
 */
final class Uuid
{
    public static function v4(): string
    {
        $bytes = random_bytes(16);
        $bytes[6] = chr((ord($bytes[6]) & 0x0F) | 0x40);
        $bytes[8] = chr((ord($bytes[8]) & 0x3F) | 0x80);

        return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($bytes), 4));
    }
}

}

namespace WatchTower\Transport {

/**
 * Minimal HTTP POST used to deliver batches. Implementations never throw.
 */
interface HttpClient
{
    /**
     * @param  array<string, string>  $headers
     * @return int The HTTP status code, or 0 when no response was received.
     */
    public function post(string $url, array $headers, string $body, float $connectTimeout, float $timeout): int;
}

}

namespace WatchTower\Transport {

/**
 * cURL transport (preferred when ext-curl is loaded).
 */
final class CurlHttpClient implements HttpClient
{
    public function post(string $url, array $headers, string $body, float $connectTimeout, float $timeout): int
    {
        try {
            $handle = curl_init($url);

            if ($handle === false) {
                return 0;
            }

            $lines = [];
            foreach ($headers as $name => $value) {
                $lines[] = $name.': '.$value;
            }
            $lines[] = 'Expect:';

            curl_setopt_array($handle, [
                CURLOPT_POST => true,
                CURLOPT_POSTFIELDS => $body,
                CURLOPT_HTTPHEADER => $lines,
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_NOSIGNAL => true,
                CURLOPT_CONNECTTIMEOUT_MS => max(1, (int) round($connectTimeout * 1000)),
                CURLOPT_TIMEOUT_MS => max(1, (int) round($timeout * 1000)),
                CURLOPT_FOLLOWLOCATION => false,
            ]);

            $result = curl_exec($handle);

            // The handle is freed when it goes out of scope (curl_close() is a no-op since PHP 8).
            return $result === false ? 0 : (int) curl_getinfo($handle, CURLINFO_RESPONSE_CODE);
        } catch (\Throwable) {
            return 0;
        }
    }
}

}

namespace WatchTower\Transport {

use WatchTower\Config;
use WatchTower\Support\Guard;
use WatchTower\WatchTower;

/**
 * Delivers record batches to `POST {base_url}/api/ingest/v1`.
 *
 * Contract: gzip-compressed `{"records":[...]}` with a Bearer environment token.
 * 2xx = accepted; 401 = stop sending for 10 minutes; 413 = split the batch in
 * half and retry; anything else (or no response) = spool to disk. Every
 * successful send also drains a few spooled batches. Nothing here throws and
 * no call blocks longer than the configured total timeout.
 */
final class Ingest
{
    public const AUTH_BACKOFF_SECONDS = 600;

    private const OK = 'ok';

    private const AUTH = 'auth';

    private const FAILED = 'failed';

    public function __construct(
        private readonly Config $config,
        private readonly HttpClient $http,
        private readonly Spool $spool,
    ) {}

    public static function defaultHttpClient(): HttpClient
    {
        return function_exists('curl_init') ? new CurlHttpClient : new StreamHttpClient;
    }

    public function spool(): Spool
    {
        return $this->spool;
    }

    /**
     * @param  list<array<string, mixed>>  $records
     */
    public function deliver(array $records): void
    {
        Guard::safely(function () use ($records): void {
            if ($records === []) {
                return;
            }

            $batches = array_chunk($records, $this->config->maxRecords);

            if ($this->config->mode === 'spool' || ! $this->config->canSend() || $this->isBackedOff()) {
                foreach ($batches as $batch) {
                    $this->spool->push($this->encode($batch));
                }

                return;
            }

            $deadline = microtime(true) + $this->config->timeout;
            $delivered = false;
            $stop = false;

            foreach ($batches as $batch) {
                $payload = $this->encode($batch);
                $result = $stop ? self::FAILED : $this->send($payload, $deadline);

                if ($result === self::OK) {
                    $delivered = true;

                    continue;
                }

                $stop = true;
                $this->spool->push($payload);
            }

            if ($delivered && ! $stop) {
                $this->drain($this->config->spoolDrainBatches, $deadline);
            }
        });
    }

    /**
     * Send spooled batches until $limit is reached, the deadline passes or a send fails.
     *
     * @return int Batches delivered.
     */
    public function drain(int $limit, ?float $deadline = null, bool $ignoreBackoff = false): int
    {
        return Guard::safely(function () use ($limit, $deadline, $ignoreBackoff): int {
            if (! $this->config->canSend() || (! $ignoreBackoff && $this->isBackedOff())) {
                return 0;
            }

            $sent = 0;

            foreach ($this->spool->claim($limit) as $claimed) {
                if ($deadline !== null && microtime(true) >= $deadline) {
                    $this->spool->release($claimed);

                    continue;
                }

                $ok = true;

                foreach ($this->spool->read($claimed) as $payload) {
                    if ($ok && $this->send($payload, $deadline ?? microtime(true) + $this->config->timeout) !== self::OK) {
                        $ok = false;
                    }
                }

                if ($ok) {
                    $this->spool->remove($claimed);
                    $sent++;
                } else {
                    $this->spool->release($claimed);
                    $deadline = 0.0;
                }
            }

            return $sent;
        }, 0);
    }

    public function isBackedOff(): bool
    {
        $file = $this->backoffFile();

        return is_file($file) && (float) @file_get_contents($file) > microtime(true);
    }

    /**
     * @param  list<array<string, mixed>>  $records
     */
    public function encode(array $records): string
    {
        $json = json_encode(['records' => $records], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            | JSON_PRESERVE_ZERO_FRACTION | JSON_INVALID_UTF8_SUBSTITUTE | JSON_PARTIAL_OUTPUT_ON_ERROR);

        return is_string($json) ? $json : '{"records":[]}';
    }

    /**
     * @return array<string, string>
     */
    public function headers(bool $gzip): array
    {
        $headers = [
            'Authorization' => 'Bearer '.$this->config->token,
            'Content-Type' => 'application/json',
            'Accept' => 'application/json',
            'User-Agent' => 'watchtower-php/'.WatchTower::VERSION,
        ];

        if ($gzip) {
            $headers['Content-Encoding'] = 'gzip';
        }

        return $headers;
    }

    private function send(string $payload, float $deadline): string
    {
        $remaining = $deadline - microtime(true);

        if ($remaining < 0.05) {
            return self::FAILED;
        }

        $gzip = function_exists('gzencode');
        $body = $gzip ? gzencode($payload, 6) : $payload;

        if ($body === false) {
            [$gzip, $body] = [false, $payload];
        }

        $timeout = min($this->config->timeout, $remaining);
        $status = $this->http->post($this->config->ingestUrl(), $this->headers($gzip), $body, min($this->config->connectTimeout, $timeout), $timeout);

        if ($status >= 200 && $status < 300) {
            return self::OK;
        }

        if ($status === 401) {
            $this->backOff();

            return self::AUTH;
        }

        if ($status === 413) {
            return $this->split($payload, $deadline);
        }

        return self::FAILED;
    }

    /** 413: halve the batch and send both parts; a single oversized record is dropped. */
    private function split(string $payload, float $deadline): string
    {
        $records = json_decode($payload, true)['records'] ?? null;

        if (! is_array($records) || count($records) <= 1) {
            return self::OK;
        }

        $half = intdiv(count($records), 2);

        foreach ([array_slice($records, 0, $half), array_slice($records, $half)] as $part) {
            $encoded = $this->encode(array_values($part));

            // A half that cannot be delivered is spooled on its own, so the
            // half that was accepted is never sent twice.
            if ($this->send($encoded, $deadline) !== self::OK) {
                $this->spool->push($encoded);
            }
        }

        return self::OK;
    }

    private function backOff(): void
    {
        if ($this->spool->ensureDirectory()) {
            @file_put_contents($this->backoffFile(), (string) (microtime(true) + self::AUTH_BACKOFF_SECONDS), LOCK_EX);
        }
    }

    private function backoffFile(): string
    {
        return $this->spool->directory().DIRECTORY_SEPARATOR.'auth-backoff-'.$this->config->tokenId();
    }
}

}

namespace WatchTower\Transport {

/**
 * On-disk fallback queue. Every undeliverable batch is written as one JSON
 * line (`{"records":[...]}`) to its own file, so concurrent PHP workers never
 * contend for a lock; batches are claimed by an atomic rename. The directory
 * is size-capped: when it is full the oldest batches are dropped.
 */
final class Spool
{
    private const PREFIX = 'batch-';

    private const SUFFIX = '.jsonl';

    private const CLAIMED = '.sending';

    /** A claim older than this is considered abandoned (worker died mid-send). */
    private const STALE_CLAIM_SECONDS = 60;

    public function __construct(
        private readonly string $directory,
        private readonly int $maxBytes,
    ) {}

    public function directory(): string
    {
        return $this->directory;
    }

    public function ensureDirectory(): bool
    {
        return is_dir($this->directory) || @mkdir($this->directory, 0775, true) || is_dir($this->directory);
    }

    /** Store one batch payload (a JSON document without newlines). */
    public function push(string $payload): bool
    {
        if (! $this->ensureDirectory()) {
            return false;
        }

        $payload = str_replace(["\r", "\n"], '', $payload)."\n";
        $this->makeRoom(strlen($payload));

        $file = $this->directory.DIRECTORY_SEPARATOR.self::PREFIX.sprintf('%.6F', microtime(true)).'-'.bin2hex(random_bytes(4)).self::SUFFIX;

        return @file_put_contents($file, $payload, LOCK_EX) !== false;
    }

    /**
     * Claim up to $limit batches, oldest first.
     *
     * @return list<string> Paths of the claimed files.
     */
    public function claim(int $limit): array
    {
        if ($limit <= 0 || ! is_dir($this->directory)) {
            return [];
        }

        $this->releaseStaleClaims();
        $claimed = [];

        foreach ($this->files() as $file) {
            if (count($claimed) >= $limit) {
                break;
            }

            $target = $file.self::CLAIMED;

            if (@rename($file, $target)) {
                @touch($target);
                $claimed[] = $target;
            }
        }

        return $claimed;
    }

    /**
     * Every line of a claimed file (normally exactly one batch).
     *
     * @return list<string>
     */
    public function read(string $claimed): array
    {
        $lines = @file($claimed, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);

        return is_array($lines) ? array_values($lines) : [];
    }

    public function remove(string $claimed): void
    {
        @unlink($claimed);
    }

    /** Return a claimed batch to the queue after a failed delivery. */
    public function release(string $claimed): void
    {
        if (str_ends_with($claimed, self::CLAIMED)) {
            @rename($claimed, substr($claimed, 0, -strlen(self::CLAIMED)));
        }
    }

    /** Number of queued (unclaimed) batches. */
    public function count(): int
    {
        return count($this->files());
    }

    public function size(): int
    {
        $total = 0;

        foreach ($this->files() as $file) {
            $total += (int) @filesize($file);
        }

        return $total;
    }

    /**
     * Queued batch files, oldest first.
     *
     * @return list<string>
     */
    private function files(): array
    {
        $files = glob($this->directory.DIRECTORY_SEPARATOR.self::PREFIX.'*'.self::SUFFIX) ?: [];
        sort($files, SORT_STRING);

        return array_values($files);
    }

    private function makeRoom(int $incoming): void
    {
        $files = $this->files();
        $sizes = [];
        $total = $incoming;

        foreach ($files as $file) {
            $sizes[$file] = (int) @filesize($file);
            $total += $sizes[$file];
        }

        foreach ($sizes as $file => $size) {
            if ($total <= $this->maxBytes) {
                break;
            }

            @unlink($file);
            $total -= $size;
        }
    }

    private function releaseStaleClaims(): void
    {
        foreach (glob($this->directory.DIRECTORY_SEPARATOR.self::PREFIX.'*'.self::SUFFIX.self::CLAIMED) ?: [] as $file) {
            $modified = @filemtime($file);

            if ($modified !== false && $modified < time() - self::STALE_CLAIM_SECONDS) {
                $this->release($file);
            }
        }
    }
}

}

namespace WatchTower\Transport {

/**
 * Fallback transport using PHP streams (no extensions needed). Streams have no
 * separate connect timeout, so the total timeout applies to both phases.
 */
final class StreamHttpClient implements HttpClient
{
    public function post(string $url, array $headers, string $body, float $connectTimeout, float $timeout): int
    {
        try {
            $lines = ['Connection: close', 'Content-Length: '.strlen($body)];
            foreach ($headers as $name => $value) {
                $lines[] = $name.': '.$value;
            }

            $context = stream_context_create([
                'http' => [
                    'method' => 'POST',
                    'header' => implode("\r\n", $lines),
                    'content' => $body,
                    'timeout' => $timeout,
                    'ignore_errors' => true,
                    'follow_location' => 0,
                    'protocol_version' => 1.1,
                ],
            ]);

            $stream = @fopen($url, 'rb', false, $context);

            if ($stream === false) {
                return 0;
            }

            $meta = stream_get_meta_data($stream);
            fclose($stream);

            return self::status(is_array($meta['wrapper_data'] ?? null) ? $meta['wrapper_data'] : []);
        } catch (\Throwable) {
            return 0;
        }
    }

    /**
     * @param  array<int, mixed>  $headers
     */
    private static function status(array $headers): int
    {
        $status = 0;

        foreach ($headers as $line) {
            if (is_string($line) && preg_match('#^HTTP/\S+\s+(\d{3})#', $line, $match) === 1) {
                $status = (int) $match[1];
            }
        }

        return $status;
    }
}

}

namespace WatchTower {

use WatchTower\Http\CurlTracer;
use WatchTower\Http\GuzzleMiddleware;
use WatchTower\Log\Logger;
use WatchTower\Support\Guard;

/**
 * Static entry point of the SDK.
 *
 *     WatchTower::init(['token' => '...', 'base_url' => 'https://watchtower.example.com']);
 *
 * Every method is safe to call before init() (it does nothing) and never throws.
 */
final class WatchTower
{
    public const VERSION = '0.1.0';

    private static ?Client $client = null;

    private static ?ErrorHandler $errors = null;

    private static ?Logger $logger = null;

    /**
     * Configure the SDK and start observing the current request or CLI script.
     *
     * @param  array<string, mixed>  $options  See README for every option.
     */
    public static function init(array $options = []): ?Client
    {
        if (self::$client !== null) {
            return self::$client;
        }

        return Guard::safely(static function () use ($options): Client {
            $client = new Client(new Config($options));
            self::$client = $client;

            if (! $client->config->enabled) {
                return $client;
            }

            if ($options['install_handlers'] ?? true) {
                self::$errors = new ErrorHandler($client);
                self::$errors->install();
            }

            if (PHP_SAPI === 'cli' || PHP_SAPI === 'phpdbg') {
                $argv = is_array($_SERVER['argv'] ?? null) ? array_map('strval', $_SERVER['argv']) : [];
                $name = (string) ($options['command_name'] ?? ($argv !== [] ? basename($argv[0]) : 'php'));
                $execution = $client->startCommand($name, $argv !== [] ? implode(' ', [$name, ...array_slice($argv, 1)]) : $name, '', is_numeric($_SERVER['REQUEST_TIME_FLOAT'] ?? null) ? (float) $_SERVER['REQUEST_TIME_FLOAT'] : null);
                $execution->meta['auto'] = true;
            } else {
                $client->startRequest($_SERVER);

                if ($client->config->captures('response_size')) {
                    $client->countResponseBytes();
                }
            }

            // Registering from inside a shutdown function puts ours last, after the application's own.
            register_shutdown_function(static function () use ($client): void {
                register_shutdown_function(static fn () => $client->shutdown(self::$errors));
            });

            return $client;
        });
    }

    public static function client(): ?Client
    {
        return self::$client;
    }

    /**
     * Name the route of this request; it becomes the request's group in Watch Tower.
     *
     * @param  list<string>|null  $methods
     */
    public static function route(string $path, ?string $name = null, ?string $action = null, ?array $methods = null): void
    {
        Guard::safely(static fn () => self::$client?->route($path, $name, $action, $methods));
    }

    /**
     * Attribute this execution to a user (also sends a `user` record).
     */
    public static function user(string|int|null $id, ?string $name = null, ?string $email = null): void
    {
        Guard::safely(static fn () => self::$client?->user($id, $name, $email));
    }

    public static function captureException(\Throwable $e, bool $handled = true): void
    {
        self::$client?->captureException($e, $handled);
    }

    /**
     * A PSR-3 logger (implements Psr\Log\LoggerInterface when psr/log is installed).
     */
    public static function logger(): Logger
    {
        return self::$logger ??= new Logger(static fn (): ?Client => self::$client);
    }

    /**
     * Run a CLI task as its own reported command.
     *
     * @template T
     *
     * @param  callable(): T  $callback
     * @return T
     */
    public static function command(string $name, callable $callback, ?bool $captureOutput = null): mixed
    {
        if (self::$client === null) {
            return $callback();
        }

        return self::$client->runCommand($name, $callback, $captureOutput);
    }

    /** Exit code reported for the automatically observed CLI script. */
    public static function exitCode(int $code): void
    {
        Guard::safely(static fn () => self::$client?->setExitCode($code));
    }

    /**
     * curl_exec() that records an outgoing-request. Pass the request headers to
     * have a W3C `traceparent` added to them.
     *
     * @param  list<string>|null  $headers
     */
    public static function curlExec(\CurlHandle $handle, ?array $headers = null): string|bool
    {
        return CurlTracer::exec(self::$client, $handle, $headers);
    }

    /**
     * Guzzle middleware: `$stack->push(WatchTower::guzzleMiddleware());`
     */
    public static function guzzleMiddleware(): callable
    {
        return GuzzleMiddleware::create(static fn (): ?Client => self::$client);
    }

    /** The `traceparent` header value to send with an outgoing call, if tracing is on. */
    public static function traceparent(): ?string
    {
        return Guard::safely(static fn () => self::$client?->traceparent());
    }

    /** Do not report the current request or script. */
    public static function ignore(): void
    {
        Guard::safely(static fn () => self::$client?->ignore());
    }

    /** Send everything buffered so far now (useful in long-running scripts). */
    public static function flush(): void
    {
        self::$client?->flush();
    }

    /**
     * Forget the SDK state and restore handlers (tests, long-running workers).
     */
    public static function reset(): void
    {
        if (self::$errors !== null) {
            @restore_error_handler();
            @restore_exception_handler();
        }

        self::$client = null;
        self::$errors = null;
        self::$logger = null;
        Client::resetProcessState();
    }
}

}

namespace WatchTower\WordPress {

use WatchTower\Client;
use WatchTower\Support\RoutePattern;

/**
 * WordPress hooks used by the `wordpress/watchtower.php` mu-plugin: request
 * routes from the main query / REST route / admin screen, the current user,
 * and `$wpdb` queries.
 *
 * Query timing: with SAVEQUERIES enabled the exact durations WordPress logs
 * are used (the caller is then the function list WordPress records). Without
 * it, a query starts at the `query` filter and ends at the next WordPress
 * hook that fires afterwards, which is an upper bound (it includes any PHP work
 * between the query and that hook), but file/line point at the real caller.
 */
final class Integration
{
    private static ?Client $client = null;

    /** @var array{sql: string, start: float, file: string, line: int}|null */
    private static ?array $pending = null;

    private static ?\Closure $closer = null;

    private static string $template = '';

    public static function register(Client $client): void
    {
        self::$client = $client;
        self::$pending = null;
        self::$template = '';

        if (function_exists('wp_doing_ajax') && wp_doing_ajax()) {
            $action = isset($_REQUEST['action']) && is_string($_REQUEST['action']) ? preg_replace('/[^a-z0-9_\-]/', '', strtolower($_REQUEST['action'])) : '';
            $client->route('/wp-admin/admin-ajax.php', 'ajax'.($action !== '' ? '.'.$action : ''));
        } elseif (function_exists('wp_doing_cron') && wp_doing_cron()) {
            $client->route('/wp-cron.php', 'cron');
        } elseif (($GLOBALS['pagenow'] ?? '') === 'wp-login.php') {
            $client->route('/wp-login.php', 'login');
        }

        add_filter('template_include', [self::class, 'template'], PHP_INT_MAX);
        add_action('wp', [self::class, 'routeFromQuery'], PHP_INT_MAX);
        add_action('current_screen', [self::class, 'routeFromScreen'], PHP_INT_MAX);
        add_filter('rest_dispatch_request', [self::class, 'routeFromRest'], 10, 4);
        add_action('init', [self::class, 'user'], PHP_INT_MAX);
        add_action('shutdown', [self::class, 'shutdown'], PHP_INT_MAX);

        if ($client->config->captures('queries') && ! (defined('SAVEQUERIES') && SAVEQUERIES)) {
            self::$closer = static function (): void {
                self::closePendingQuery();
            };
            add_filter('query', [self::class, 'queryStarted'], PHP_INT_MAX);
        }
    }

    /** `template_include` filter: remember the theme template that renders the page. */
    public static function template(mixed $template): mixed
    {
        if (is_string($template) && $template !== '') {
            self::$template = basename($template);
            self::routeFromQuery();
        }

        return $template;
    }

    /** `wp` action: name the request after the template type of the main query. */
    public static function routeFromQuery(): void
    {
        try {
            if (self::$client === null) {
                return;
            }

            [$path, $name] = self::templateRoute();
            self::$client->route($path, $name, self::$template !== '' ? 'theme/'.self::$template : null);
        } catch (\Throwable) {
            // Never break the page.
        }
    }

    /** `current_screen` action (wp-admin). */
    public static function routeFromScreen(mixed $screen = null): void
    {
        try {
            $page = (string) ($GLOBALS['pagenow'] ?? 'index.php');
            $id = is_object($screen) && isset($screen->id) ? (string) $screen->id : basename($page, '.php');
            self::$client?->route('/wp-admin/'.$page, 'admin.'.$id);
        } catch (\Throwable) {
        }
    }

    /** `rest_dispatch_request` filter: `/wp/v2/posts/(?P<id>[\d]+)` becomes `/wp-json/wp/v2/posts/{id}`. */
    public static function routeFromRest(mixed $result, mixed $request = null, mixed $route = null, mixed $handler = null): mixed
    {
        try {
            if (is_string($route) && self::$client !== null) {
                $method = is_object($request) && method_exists($request, 'get_method') ? (string) $request->get_method() : null;
                self::$client->route('/wp-json'.RoutePattern::fromRegex($route), 'rest', null, $method !== null ? [$method] : null);
            }
        } catch (\Throwable) {
        }

        return $result;
    }

    /** `init` / `shutdown`: attribute the request to the logged-in user (login name, never the email). */
    public static function user(): void
    {
        try {
            if (self::$client === null || ! function_exists('wp_get_current_user')) {
                return;
            }

            $user = wp_get_current_user();

            if (is_object($user) && isset($user->ID) && (int) $user->ID > 0) {
                self::$client->user((int) $user->ID, (string) ($user->display_name ?? ''), (string) ($user->user_login ?? ''));
            }
        } catch (\Throwable) {
        }
    }

    public static function shutdown(): void
    {
        self::closePendingQuery();
        self::user();
        self::recordSavedQueries();
    }

    /** `query` filter: a `$wpdb` query is about to run. */
    public static function queryStarted(mixed $sql): mixed
    {
        try {
            self::closePendingQuery();

            if (! is_string($sql) || self::$client === null || self::$closer === null) {
                return $sql;
            }

            [$file, $line] = self::$client->location->find(debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS, 30));
            self::$pending = ['sql' => $sql, 'start' => microtime(true), 'file' => $file, 'line' => $line];
            add_filter('all', self::$closer);
        } catch (\Throwable) {
        }

        return $sql;
    }

    /** The next hook after a query (or shutdown) ends it. */
    public static function closePendingQuery(): void
    {
        $pending = self::$pending;

        if ($pending === null) {
            return;
        }

        self::$pending = null;

        try {
            if (self::$closer !== null) {
                remove_filter('all', self::$closer);
            }

            self::$client?->query($pending['sql'], $pending['start'], (int) round((microtime(true) - $pending['start']) * 1_000_000), 'wpdb', $pending['file'], $pending['line']);
        } catch (\Throwable) {
        }
    }

    /** SAVEQUERIES: exact durations from `$wpdb->queries` ([sql, seconds, callers, start, data]). */
    private static function recordSavedQueries(): void
    {
        try {
            global $wpdb;

            if (! (defined('SAVEQUERIES') && SAVEQUERIES) || self::$client === null || ! is_object($wpdb) || ! is_array($wpdb->queries ?? null)
                || ! self::$client->config->captures('queries')) {
                return;
            }

            $now = microtime(true);

            foreach ($wpdb->queries as $query) {
                if (! is_array($query) || ! is_string($query[0] ?? null)) {
                    continue;
                }

                $seconds = is_numeric($query[1] ?? null) ? (float) $query[1] : 0.0;
                $start = is_numeric($query[3] ?? null) ? (float) $query[3] : $now - $seconds;
                $callers = array_map('trim', explode(',', (string) ($query[2] ?? '')));

                self::$client->query($query[0], $start, (int) round($seconds * 1_000_000), 'wpdb', (string) end($callers), 0);
            }

            $wpdb->queries = [];
        } catch (\Throwable) {
        }
    }

    /**
     * @return array{0: string, 1: string}
     */
    private static function templateRoute(): array
    {
        $is = static fn (string $tag): bool => function_exists($tag) && (bool) $tag();

        return match (true) {
            $is('is_404') => ['', 'wp.404'],
            $is('is_feed') => ['/feed', 'wp.feed'],
            $is('is_search') => ['/search', 'wp.search'],
            $is('is_front_page') => ['/', 'wp.front_page'],
            $is('is_home') => ['/{posts_page}', 'wp.home'],
            $is('is_attachment') => ['/attachment/{slug}', 'wp.attachment'],
            $is('is_page') => ['/{page}', 'wp.page'],
            $is('is_singular') => ['/'.self::postType().'/{slug}', 'wp.single.'.self::postType()],
            $is('is_category') => ['/category/{slug}', 'wp.category'],
            $is('is_tag') => ['/tag/{slug}', 'wp.tag'],
            $is('is_tax') => ['/{taxonomy}/{term}', 'wp.taxonomy'],
            $is('is_author') => ['/author/{author}', 'wp.author'],
            $is('is_date') => ['/{date}', 'wp.date'],
            $is('is_post_type_archive') => ['/'.self::postType(), 'wp.archive.'.self::postType()],
            $is('is_archive') => ['/{archive}', 'wp.archive'],
            default => ['/', 'wp'],
        };
    }

    private static function postType(): string
    {
        $type = function_exists('get_post_type') ? get_post_type() : null;

        if (! is_string($type) && function_exists('get_query_var')) {
            $type = get_query_var('post_type');
            $type = is_array($type) ? reset($type) : $type;
        }

        return is_string($type) && $type !== '' ? $type : 'post';
    }

    /** @internal */
    public static function reset(): void
    {
        self::$client = null;
        self::$pending = null;
        self::$closer = null;
        self::$template = '';
    }
}

}

namespace {

use WatchTower\WatchTower;

/*
 * Lets plain PHP code call `WatchTower::init([...])` without a `use` statement.
 */
if (! class_exists('WatchTower', false)) {
    class_alias(WatchTower::class, 'WatchTower');
}

}
